// Third-person camera that follows the local player's kart.
defineScript({
  name: 'ChaseCamera',
  description: 'Smooth chase camera behind the local kart.',
  props: {
    distance: { type: 'number', default: 9, min: 2, max: 40 },
    height: { type: 'number', default: 4.5, min: 0.5, max: 30 },
    lookAhead: { type: 'number', default: 6, min: 0, max: 40 },
    smoothing: { type: 'number', default: 5, min: 0, max: 30 },
  },
  onLateUpdate(ctx, dt) {
    let target;
    for (const e of ctx.findAll('kart')) {
      const pi = ctx.getOn(e, 'PlayerInput');
      if (pi && (pi.owner === 'local' || pi.owner === ctx.net.localId)) { target = e; break; }
    }
    if (target === undefined) return;
    const kt = ctx.getOn(target, 'Transform');
    const rb = ctx.getOn(target, 'RigidBody3D');
    const speed = rb ? Math.hypot(rb.velocity.x, rb.velocity.z) : 0;
    // Kart forward in the XZ plane (yaw rotation of +Z).
    const q = kt.rotation;
    const fx = 2 * (q.x * q.z + q.w * q.y), fz = 1 - 2 * (q.x * q.x + q.y * q.y);
    const dist = ctx.props.distance + speed * 0.08;
    const tx = kt.x - fx * dist, ty = kt.y + ctx.props.height, tz = kt.z - fz * dist;
    const t = ctx.transform;
    const k = ctx.props.smoothing;
    t.setPosition(ctx.math.damp(t.x, tx, k, dt), ctx.math.damp(t.y, ty, k, dt), ctx.math.damp(t.z, tz, k, dt));
    t.lookAt(new ctx.math.Vec3(kt.x + fx * ctx.props.lookAhead, kt.y + 1, kt.z + fz * ctx.props.lookAhead));
  },
});

// Checkpoint marker data (read by the Kart script) plus a gentle bar pulse.
defineScript({
  name: 'Checkpoint',
  description: 'Ordered race checkpoint; index 0 is the start/finish line.',
  props: {
    index: { type: 'integer', default: 0, min: 0 },
    halfX: { type: 'number', default: 7 },
    halfZ: { type: 'number', default: 0.8 },
    heading: { type: 'number', default: 0, label: 'Respawn heading (rad)' },
  },
  onUpdate(ctx) {
    for (const child of ctx.world.getChildren(ctx.entity)) {
      if (ctx.nameOf(child) !== 'Bar') continue;
      const mr = ctx.getOn(child, 'MeshRenderer');
      if (mr) mr.emissive.a = 1, mr.opacity = 0.55 + Math.sin(ctx.time.elapsed * 3 + ctx.props.index) * 0.25;
    }
  },
});

// Race director: puts one Kart per player on the grid, runs the countdown,
// tracks laps and declares the winner.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }

const COLORS = ['#ff7a3d', '#4cc2ff', '#8b7dff', '#ffd166', '#06d6a0', '#ef476f'];

defineScript({
  name: 'GameManager',
  description: 'Grid, countdown, laps and winner.',
  props: {
    laps: { type: 'integer', default: 3, min: 1, max: 20 },
    countdown: { type: 'integer', default: 3, min: 0, max: 10 },
    gridX: { type: 'number', default: 28, label: 'Grid centre X' },
    gridZ: { type: 'number', default: 4, label: 'Grid centre Z' },
    heading: { type: 'number', default: 3.14159, label: 'Start heading (rad)' },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.players = {};
    s.count = 0;
    s.unsub = [];
    s.finished = false;
    if (ctx.net.isHost) {
      this.addPlayer(ctx, ctx.net.localId);
      const sync = ctx.net.hub.sync;
      if (sync) {
        for (const p of sync.players()) if (p.peerId !== ctx.net.localId) this.addPlayer(ctx, p.peerId);
        s.unsub.push(sync.on('playerJoined', ({ peerId }) => this.addPlayer(ctx, peerId)));
        s.unsub.push(sync.on('playerLeft', ({ peerId }) => this.removePlayer(ctx, peerId)));
      }
      this.startCountdown(ctx);
    }
    this.drawStandings(ctx);
  },
  onDestroy(ctx) {
    for (const off of ctx.state.unsub) off();
    const h = hud(ctx);
    if (h) { h.remove('countdown'); h.remove('standings'); h.remove('winner'); h.remove('hint'); }
  },
  gridSlot(ctx, index) {
    // Two columns, staggered rows, behind the start line.
    const col = index % 2, row = Math.floor(index / 2);
    return { x: ctx.props.gridX + (col === 0 ? -2.5 : 2.5), y: 0.6, z: ctx.props.gridZ + row * 3.5 + col * 1.5 };
  },
  addPlayer(ctx, peerId) {
    const s = ctx.state;
    if (s.players[peerId]) return;
    const index = s.count++;
    const slot = this.gridSlot(ctx, index);
    const entity = ctx.net.spawn('Kart', { ownerId: peerId, position: slot });
    const pi = ctx.getOn(entity, 'PlayerInput');
    if (pi) pi.owner = peerId;
    const ni = ctx.getOn(entity, 'NetworkIdentity');
    if (ni) ni.ownerId = peerId;
    const name = ctx.getOn(entity, 'Name');
    if (name) name.name = `Kart ${peerId}`;
    const script = ctx.getOn(entity, 'Script');
    script.props.color = COLORS[index % COLORS.length];
    script.props.label = `P${index + 1}`;
    script.props.heading = ctx.props.heading;
    script.props.laps = ctx.props.laps;
    s.players[peerId] = { entity, index, lap: 0, best: 0 };
    if (s.raceStarted) ctx.sendTo(entity, 'go');
  },
  removePlayer(ctx, peerId) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    if (ctx.world.isAlive(p.entity)) {
      const sync = ctx.net.hub.sync;
      if (sync) sync.despawn(p.entity); else ctx.destroy(p.entity);
    }
    delete ctx.state.players[peerId];
  },
  startCountdown(ctx) {
    const s = ctx.state;
    s.raceStarted = false;
    let n = ctx.props.countdown;
    const h = hud(ctx);
    const tick = () => {
      if (n > 0) {
        if (h) h.text('countdown', String(n), { anchor: 'center' }).style.fontSize = '72px';
        ctx.audio.play('beep', { volume: 0.5 });
        n--;
        ctx.timer(1, tick);
      } else {
        if (h) { h.text('countdown', 'GO!', { anchor: 'center' }); ctx.timer(1, () => h.remove('countdown')); }
        ctx.audio.play('go', { volume: 0.6 });
        s.raceStarted = true;
        ctx.send('go', {});
      }
    };
    tick();
  },
  onMessage(ctx, name, data) {
    if (!ctx.net.isHost) return;
    if (name === 'lapDone') {
      const p = ctx.state.players[data.peer];
      if (!p) return;
      p.lap = data.lap;
      p.best = p.best ? Math.min(p.best, data.time) : data.time;
      this.drawStandings(ctx);
      if (p.lap >= ctx.props.laps && !ctx.state.finished) this.finish(ctx, data.peer);
    }
  },
  finish(ctx, peerId) {
    const s = ctx.state;
    s.finished = true;
    const p = s.players[peerId];
    const h = hud(ctx);
    if (h) h.panel('winner', `P${p.index + 1} wins!`, `Best lap ${p.best.toFixed(2)}s\nRestarting in 6s`);
    ctx.audio.play('go', { volume: 0.6 });
    ctx.timer(6, () => {
      for (const q of Object.values(s.players)) {
        q.lap = 0; q.best = 0;
        const slot = this.gridSlot(ctx, q.index);
        ctx.sendTo(q.entity, 'resetTo', slot);
      }
      s.finished = false;
      if (h) h.remove('winner');
      this.drawStandings(ctx);
      this.startCountdown(ctx);
    });
  },
  drawStandings(ctx) {
    const h = hud(ctx);
    if (!h) return;
    const rows = Object.values(ctx.state.players).sort((a, b) => b.lap - a.lap || (a.best || 1e9) - (b.best || 1e9))
      .map((p, i) => `${i + 1}. P${p.index + 1}  lap ${p.lap}/${ctx.props.laps}${p.best ? `  best ${p.best.toFixed(2)}s` : ''}`);
    h.text('standings', rows.join('\n'), { anchor: 'top-right', y: 48 });
    h.text('hint', 'W/S throttle · A/D steer · E reset kart', { anchor: 'bottom-right' });
  },
});

// Arcade kart on top of RigidBody3D: throttle along the heading, steering
// scaled by speed, lateral grip, checkpoint/lap tracking and a per-player HUD.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }

defineScript({
  name: 'Kart',
  description: 'Drivable kart with lap timing.',
  props: {
    accel: { type: 'number', default: 18, min: 1, max: 100 },
    brake: { type: 'number', default: 30, min: 1, max: 200 },
    maxSpeed: { type: 'number', default: 22, min: 1, max: 100 },
    reverseSpeed: { type: 'number', default: 7, min: 0, max: 50 },
    turnSpeed: { type: 'number', default: 2.4, min: 0.1, max: 10, label: 'Turn rate (rad/s)' },
    grip: { type: 'number', default: 12, min: 0, max: 60, label: 'Grip (velocity blend rate)' },
    heading: { type: 'number', default: 3.14159 },
    laps: { type: 'integer', default: 3 },
    color: { type: 'string', default: '#ff7a3d', label: 'Colour (hex)' },
    label: { type: 'string', default: 'P1' },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.h = ctx.props.heading;
    s.go = false;
    s.next = 1;
    s.lap = 0;
    s.lapStart = 0;
    s.best = 0;
    s.steer = 0;
    s.speed = 0;
    s.lastCheckpoint = { x: ctx.transform.x, y: ctx.transform.y, z: ctx.transform.z, h: s.h };
    ctx.transform.setEuler(0, s.h, 0);
    this.applyLook(ctx);
    s.offCollision = ctx.physics3d.events.on('collisionEnter', (ev) => {
      if (ev.a !== ctx.entity && ev.b !== ctx.entity) return;
      const rb = ctx.get('RigidBody3D');
      const sp = Math.hypot(rb.velocity.x, rb.velocity.z);
      if (sp > 4) ctx.audio.play('hit', { volume: Math.min(1, sp / 20), pitchVariation: 0.15 });
    });
  },
  onDestroy(ctx) {
    if (ctx.state.offCollision) ctx.state.offCollision();
    const h = hud(ctx);
    if (h && this.isLocal(ctx)) h.remove('lap');
  },
  onReload(ctx) { this.applyLook(ctx); },
  applyLook(ctx) {
    for (const child of ctx.world.getChildren(ctx.entity)) {
      const n = ctx.nameOf(child);
      const mr = ctx.getOn(child, 'MeshRenderer');
      if (mr && (n === 'Body' || n === 'Nose')) mr.color.setHex(ctx.props.color);
    }
  },
  isLocal(ctx) {
    const pi = ctx.playerInput;
    return !!pi && (pi.owner === 'local' || pi.owner === ctx.net.localId);
  },
  forward(ctx) { return { x: Math.sin(ctx.state.h), z: Math.cos(ctx.state.h) }; },

  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (name === 'go') { s.go = true; s.lapStart = ctx.time.elapsed; s.next = 1; s.lap = 0; }
    else if (name === 'resetTo') { this.teleport(ctx, data.x, data.y, data.z, ctx.props.heading); s.go = false; s.lap = 0; s.next = 1; s.best = 0; }
  },
  teleport(ctx, x, y, z, h) {
    const rb = ctx.get('RigidBody3D');
    rb.velocity.set(0, 0, 0);
    ctx.state.speed = 0;
    ctx.state.h = h;
    ctx.transform.setPosition(x, y, z);
    ctx.transform.setEuler(0, h, 0);
  },

  onOwnerInput(ctx, snap, dt) {
    const s = ctx.state;
    const rb = ctx.get('RigidBody3D');
    if (snap.pressed.includes('action')) {
      const c = s.lastCheckpoint;
      this.teleport(ctx, c.x, c.y + 0.5, c.z, c.h);
    }
    if (!s.go) return;
    const throttle = snap.axes.moveY || 0;
    const steer = snap.axes.moveX || 0;
    const f = this.forward(ctx);
    const actual = rb.velocity.x * f.x + rb.velocity.z * f.z;   // measured speed along the heading
    if (Math.abs(actual - s.speed) > 5) s.speed = actual;         // we hit something: accept the new speed
    if (throttle > 0.05) s.speed = ctx.math.moveToward(s.speed, ctx.props.maxSpeed * throttle, (s.speed < 0 ? ctx.props.brake : ctx.props.accel) * dt);
    else if (throttle < -0.05) s.speed = ctx.math.moveToward(s.speed, ctx.props.reverseSpeed * throttle, (s.speed > 0 ? ctx.props.brake : ctx.props.accel) * dt);
    else s.speed = ctx.math.moveToward(s.speed, 0, 5 * dt);
    // Steering authority grows with speed and flips in reverse.
    const speedFactor = ctx.math.clamp(Math.abs(s.speed) / 6, 0, 1) * Math.sign(s.speed || 1);
    s.h -= steer * ctx.props.turnSpeed * speedFactor * dt;
    s.steer = ctx.math.damp(s.steer, steer, 10, dt);
    const nf = this.forward(ctx);
    // Blend the horizontal velocity toward the heading: high grip = tight, low grip = drifty.
    const k = Math.min(1, ctx.props.grip * dt);
    rb.velocity.x += (nf.x * s.speed - rb.velocity.x) * k;
    rb.velocity.z += (nf.z * s.speed - rb.velocity.z) * k;
    ctx.transform.setEuler(0, s.h, 0);
  },
  onFixedUpdate(ctx) {
    const s = ctx.state;
    const t = ctx.transform;
    // Body roll from steering.
    const body = ctx.world.getChildren(ctx.entity).find((c) => ctx.nameOf(c) === 'Body');
    if (body !== undefined) ctx.getOn(body, 'Transform').setEuler(0, 0, -s.steer * 0.12);
    if (t.y < -5) { const c = s.lastCheckpoint; this.teleport(ctx, c.x, c.y + 0.5, c.z, c.h); }
    if (!s.go) return;
    for (const cp of ctx.findAll('checkpoint')) {
      const p = ctx.getOn(cp, 'Script').props;
      const ct = ctx.getOn(cp, 'Transform');
      if (Math.abs(t.x - ct.x) > p.halfX || Math.abs(t.z - ct.z) > p.halfZ) continue;
      if (p.index !== s.next) continue;
      const count = ctx.findAll('checkpoint').length;
      s.next = (p.index + 1) % count;
      s.lastCheckpoint = { x: ct.x, y: ct.y, z: ct.z, h: p.heading };
      if (p.index === 0) {
        s.lap++;
        const time = ctx.time.elapsed - s.lapStart;
        s.lapStart = ctx.time.elapsed;
        s.best = s.best ? Math.min(s.best, time) : time;
        ctx.audio.play('lap', { volume: 0.6 });
        ctx.send('lapDone', { peer: ctx.net.owner(), lap: s.lap, time });
      } else ctx.audio.play('checkpoint', { volume: 0.4 });
    }
  },
  onUpdate(ctx) {
    if (!this.isLocal(ctx) || ctx.time.frame % 6 !== 0) return;
    const h = hud(ctx);
    if (!h) return;
    const s = ctx.state;
    const rb = ctx.get('RigidBody3D');
    const kmh = Math.round(Math.hypot(rb.velocity.x, rb.velocity.z) * 6);
    const lapTime = s.go ? (ctx.time.elapsed - s.lapStart).toFixed(1) : '0.0';
    h.text('lap', `Lap ${Math.min(s.lap + 1, ctx.props.laps)} / ${ctx.props.laps}   ${lapTime}s${s.best ? `   best ${s.best.toFixed(2)}s` : ''}\n${kmh} km/h`, { anchor: 'top-left' });
  },
});
